  cover: "G:iDYUhedD6BM0Tg0zZeg-P_qF5zbnCu9L0Gjg4DjT1VBYGYM0BvuoQOS79BvmD7UxizuG_wMNTsYKi42SFGl1bBRQeapBeK_jUl73?uuid=f26c14aa-ed01-4048-a52f-b53c454c13ee",
